import { describe, test } from 'node:test'
import assert from 'node:assert/strict'
import DUT from '@/cloud/devices/F3M2CYK__'
import type { Metadata } from '@/cloud/thinq'
import { MockHAConnection, MockThinq2Device, buf, captureLog } from '@/tests/helpers/mocks'

const DEVICE_ID = 'test-id'
const MODEL_ID = 'F3M2CYK__'
const META: Metadata = { modelId: MODEL_ID, modelName: 'F3M2CYK__', swVersion: '0.0.0' }

// This washer's real traffic is 0xCD (idle keepalive, ~409 bytes) and 0xBD (event, ~410-480 bytes) —
// it never sends the 0xEC/0xEB frames the handler was originally written for (see the comment above
// processAABB in the source file). All 0xCD/0xBD fixtures below are REAL frames taken verbatim from a
// ~2-day capture of the physical appliance (device 826dbe82-...), spanning one Warm/Medium/TurboWash
// load (total 53 min) and a second Rinse+Spin load (total 18 min, no Washing phase).

// ── 0xCD (idle keepalive) — first load, Warm/Medium/TurboWash, total 53 min ─────────────────────────

const CD_WASHING = buf(
    '',
)
const CD_RINSING = buf(
    '',
)
const CD_SPINNING = buf(
    '',
)
const CD_COMPLETE = buf(
    '',
)

// Second load, Rinse+Spin: total=remaining=18, phase goes straight to Rinsing — no Washing phase
// (matches the physical panel for that course).
const CD_SECOND_LOAD_RINSING = buf(
    '',
)

// ── 0xBD (event, sent on phase/state changes) ────────────────────────────────────────────────────────

const BD_SELECTING = buf(
    '',
)
const BD_SENSING = buf(
    '',
)
const BD_WASHING = buf(
    '',
)
const BD_RINSING = buf(
    '',
)
// The 476-byte-body variant seen while spinning (larger than the usual ~406) — must decode the same way.
const BD_SPINNING_LARGE = buf(
    '',
)

// Second load, Rinse+Spin, at the Selecting step just before start: total already committed to 18.
const BD_SECOND_LOAD_SELECTING = buf(
    '',
)

// A real 0xEB single-record frame for this same washer model family (F3L2CYU__, offsets identical) —
// this washer never actually sends these, but the dispatcher must still route them correctly.
const EB_RECONNECT_IDLE = buf('aa2020eb001805000000000000000000000000000000000000003318000068bb')

// Frames too short to hold phase/remaining/total — must be ignored without throwing.
const CD_TOO_SHORT = buf('AA0620CD000102BB')
const BD_TOO_SHORT = buf('AA0620BD000102BB')

// Same as CD_WASHING but with the class byte changed from 0x20 (washer) to 0x30 (dryer) — must be
// ignored.
const CD_WRONG_CLASS = buf(CD_WASHING.toString('hex').replace(/^aa0020/i, 'aa0030'))

// Real mystery frames, currently undecoded: 0xD8 (by far the most frequent frame type in the
// capture, ~80 over 2 days) and an unidentified 0x7F type (~10 over 2 days).
const MYSTERY_D8 = buf('AA0720D800FCBB')
const MYSTERY_7F = buf('AA09207F010040C6BB')

function makeDevice() {
    const ha = new MockHAConnection()
    const thinq = new MockThinq2Device(DEVICE_ID, META)
    const dev = new DUT(ha.asConnection(), thinq, META)
    return { ha, thinq, dev }
}

describe(MODEL_ID, () => {
    test('config exposes remaining_time and a separate initial_time, both plain-minute durations', () => {
        const { ha } = makeDevice()
        const cfg = ha.devices[DEVICE_ID].config
        assert.ok(cfg, 'config published on construction')
        const components = cfg!.components as Record<string, Record<string, unknown>>
        for (const c of ['remaining_time', 'initial_time', 'power', 'status']) {
            assert.ok(components[c], `component ${c} present`)
        }
        assert.equal(components.initial_time.device_class, 'duration')
        assert.equal(components.initial_time.unit_of_measurement, 'min')
    })

    test('0xCD frames decode phase/power/remaining/initial across a full wash cycle (real captures)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties

        for (const [frame, status, remaining, initial] of [
            [CD_WASHING, 'Washing', 49, 53],
            [CD_RINSING, 'Rinsing', 29, 53],
            [CD_SPINNING, 'Spinning', 13, 53],
            [CD_COMPLETE, 'Complete', 1, 0],
        ] as const) {
            thinq.emit('data', frame)
            assert.equal(p.status, status)
            assert.equal(p.power, 'ON')
            assert.equal(p.remaining_time, remaining)
            assert.equal(p.initial_time, initial)
        }
    })

    test('0xCD second load goes straight to Rinsing with total=remaining=18 (real capture)', () => {
        const { ha, thinq } = makeDevice()
        thinq.emit('data', CD_SECOND_LOAD_RINSING)
        const p = ha.devices[DEVICE_ID].properties
        assert.equal(p.status, 'Rinsing')
        assert.equal(p.remaining_time, 14)
        assert.equal(p.initial_time, 18)
    })

    test('0xBD frames decode phase/power/remaining/initial across a full wash cycle (real captures)', () => {
        const { ha, thinq } = makeDevice()
        const p = ha.devices[DEVICE_ID].properties

        for (const [frame, status, remaining, initial] of [
            [BD_SELECTING, 'Selecting', 1, 0],
            [BD_SENSING, 'Sensing', 46, 46],
            [BD_WASHING, 'Washing', 33, 53],
            [BD_RINSING, 'Rinsing', 18, 53],
            [BD_SPINNING_LARGE, 'Spinning', 1, 53],
        ] as const) {
            thinq.emit('data', frame)
            assert.equal(p.status, status)
            assert.equal(p.power, 'ON')
            assert.equal(p.remaining_time, remaining)
            assert.equal(p.initial_time, initial)
        }
    })

    test('0xBD second load Selecting reports total already committed to 18 (real capture)', () => {
        const { ha, thinq } = makeDevice()
        thinq.emit('data', BD_SECOND_LOAD_SELECTING)
        const p = ha.devices[DEVICE_ID].properties
        assert.equal(p.status, 'Selecting')
        assert.equal(p.remaining_time, 18)
        assert.equal(p.initial_time, 18)
    })

    test('the pre-existing 0xEB/0xEC dispatch still works after adding 0xCD/0xBD (real capture)', () => {
        const { ha, thinq } = makeDevice()
        thinq.emit('data', EB_RECONNECT_IDLE)
        const props = ha.devices[DEVICE_ID].properties
        assert.equal(props.status, 'Selecting')
        assert.equal(props.power, 'ON')
    })

    // ── Ignored packet tests ──────────────────────────────────────────────────

    test('0xCD/0xBD frames too short to hold phase/remaining/initial are ignored', () => {
        const { ha, thinq } = makeDevice()
        thinq.emit('data', CD_TOO_SHORT)
        thinq.emit('data', BD_TOO_SHORT)
        assert.equal(ha.devices[DEVICE_ID].properties.status, undefined)
    })

    test('frames with wrong device class byte (not 0x20) are ignored', () => {
        const { ha, thinq } = makeDevice()
        thinq.emit('data', CD_WRONG_CLASS)
        assert.equal(ha.devices[DEVICE_ID].properties.status, undefined)
    })

    // ── Logging (for future status-code hunting) ────────────────────────────────

    test('undecoded frame types (0xD8, 0x7F) are logged (real captures)', () => {
        const { thinq } = makeDevice()
        const cap = captureLog()
        try {
            thinq.emit('data', MYSTERY_D8)
            thinq.emit('data', MYSTERY_7F)
            assert.equal(cap.calls.length, 2)
            for (const call of cap.calls) {
                const [, topic, message] = call.arguments
                assert.equal(topic, 'F3M2CYK__')
                assert.equal(message, 'unrecognized frame')
            }
            assert.equal(cap.calls[0].arguments[3], MYSTERY_D8.subarray(2, -2).toString('hex'))
            assert.equal(cap.calls[1].arguments[3], MYSTERY_7F.subarray(2, -2).toString('hex'))
        } finally {
            cap.restore()
        }
    })
})
